-- Supplemental evidence query for the CFO findings; not one of the ten scored questions.\nSELECT substr(d.full_date,1,7) month,dept.plant_name,dept.department_name,COUNT(*) missing_punch_days FROM fact_attendance_daily a JOIN dim_date d ON d.date_key=a.date_key JOIN dim_employee e ON e.employee_key=a.employee_key JOIN dim_department dept ON dept.department_key=e.department_key WHERE a.status='Missing Punch' GROUP BY month,dept.plant_name,dept.department_name ORDER BY month,dept.plant_name,dept.department_name;\n